W = 6
H, G = "HRM-theorie", "Gespreksvoering"
# Arbeidsrecht les 6 is uitloop zonder nieuwe stof, dus deze week alleen HRM-theorie en gespreksvoering.

# ---------- HRM-theorie MC ----------
mc("hrm6-h01", W, H, "Wanneer is er volgens de definitie uit het college sprake van ziekteverzuim?",
   ["Als iemand zich ziek meldt", "Als iemand een aantoonbare ziekte of gebrek heeft én daardoor ongeschikt is voor het werk", "Als de bedrijfsarts dat heeft vastgesteld", "Als iemand langer dan een week afwezig is"], 1,
   "Twee elementen: een aantoonbare ziekte of gebrek, en daardoor ongeschikt voor het werk (bron op de slide: vzinfo.nl). Een ziekmelding alleen is dus nog geen ziekteverzuim in deze zin.")
mc("hrm6-h02", W, H, "Een medewerker kan fysiek werken, maar meldt zich ziek omdat hij moe en niet gemotiveerd is. Welk soort verzuim is dit?",
   ["Wit verzuim", "Grijs verzuim", "Zwart verzuim", "Geen verzuim"], 1,
   "Grijs verzuim is een onduidelijk ziektebeeld: fysiek kan iemand werken, maar hij is moe of niet gemotiveerd. Wit verzuim is aantoonbaar ziek, zwart verzuim is ziek melden zonder ziekte.")
mc("hrm6-h03", W, H, "Een schoonmaker meldt zich ziek om een lang weekend weg te kunnen, terwijl hij niet ziek is. Welk soort verzuim is dit?",
   ["Wit verzuim", "Grijs verzuim", "Zwart verzuim", "Kortdurend wit verzuim"], 2,
   "Zwart verzuim: geen ziekte, toch ziek gemeld.")
mc("hrm6-h04", W, H, "Een receptioniste is drie weken ziek. Hoe heet dit verzuim naar duur, volgens het college?",
   ["Kortdurend", "Middellang", "Langdurend", "Chronisch"], 1,
   "Kortdurend is maximaal een week, middellang een tot zes weken, langdurend langer dan zes weken.")
mc("hrm6-h05", W, H, "Je wilt weten hoe vaak medewerkers zich gemiddeld per jaar ziek melden, los van hoe lang ze wegblijven. Welke gangbare verzuimmaat gebruik je?",
   ["Verzuimpercentage", "Meldingsfrequentie", "Gemiddelde verzuimduur", "Nulverzuim"], 1,
   "De meldingsfrequentie is het gemiddelde aantal ziekmeldingen per medewerker per jaar. Het verzuimpercentage zijn de verzuimde dagen als percentage van de beschikbare dagen; nulverzuim is het percentage medewerkers zonder ziekmelding. De kengetallen stonden als afbeelding op de slide, dit is de gangbare indeling.")
mc("hrm6-h06", W, H, "Waarvoor is de facility manager volgens het college verantwoordelijk als het gaat om gezondheid?",
   ["Voor de gezondheid van de medewerkers zelf", "Voor de omstandigheden waarin gezondheid behouden, versterkt of juist belast wordt", "Alleen voor de ziekmeldingen", "Nergens voor, dat is de taak van de bedrijfsarts"], 1,
   "Kernzin: FM is niet verantwoordelijk voor de gezondheid zelf, maar wél voor de omstandigheden. Denk aan werkplek, ergonomie, binnenklimaat, roosters en materiaal, waar je direct invloed op hebt.")
mc("hrm6-h07", W, H, "Wat is géén doel van de Wet verbetering poortwachter?",
   ["Langdurig verzuim voorkomen", "Snelle terugkeer naar werk stimuleren", "Controleren of de werknemer echt ziek is", "Focus op wat iemand nog wél kan"], 2,
   "De Wvp wil langdurig verzuim voorkomen, snelle terugkeer stimuleren, werkgever en werknemer samen verantwoordelijk maken en focussen op wat iemand nog kan. Controleren of iemand 'echt' ziek is, hoort daar niet bij.")
mc("hrm6-h08", W, H, "Een schoonmaker kan na langdurige ziekte niet meer terug in eigen of ander werk bij zijn werkgever. Daarom zoekt men werk bij een andere werkgever. Hoe heet dit volgens de gangbare uitleg?",
   ["Spoor 1", "Spoor 2", "Plan van aanpak", "Eerstejaarsevaluatie"], 1,
   "Spoor 1 is re-integratie bij de eigen werkgever (eigen, aangepast of ander werk), spoor 2 bij een andere werkgever als terugkeer bij de eigen werkgever niet lukt. De sporen stonden als afbeelding op de slide.")
mc("hrm6-h09", W, H, "Wat mag je als facility manager onder de AVG wél doen bij verzuim?",
   ["De diagnose noteren in het personeelsdossier", "Verzuim feitelijk administreren, zoals de data van ziekmelding en herstel", "Zelf oordelen of iemand medisch geschikt is", "Aandringen op sneller herstel"], 1,
   "Gezondheidsgegevens zijn een bijzondere categorie persoonsgegevens. Je mag functioneel informeren (werkgerelateerd), verzuim feitelijk administreren, re-integratie organiseren via de bedrijfsarts en contact houden zonder medische druk.")
mc("hrm6-h10", W, H, "Waar richt de bedrijfsarts zich volgens het college op?",
   ["Op genezing van de werknemer", "Op belastbaarheid en werkvermogen", "Op het belang van de werkgever", "Op het voorschrijven van medicijnen"], 1,
   "De bedrijfsarts is een onafhankelijk medisch adviseur, gespecialiseerd in arbeid en gezondheid, en richt zich op belastbaarheid en werkvermogen, niet op genezing.")
mc("hrm6-h11", W, H, "Welke informatie geeft de bedrijfsarts aan de werkgever?",
   ["De diagnose en de behandeling", "Alleen de noodzakelijke informatie: functionele mogelijkheden, vermoedelijke duur en mogelijke aanpassingen", "Het volledige medische dossier", "Niets, de werkgever krijgt geen informatie"], 1,
   "De bedrijfsarts deelt alleen wat de werkgever nodig heeft om het werk te organiseren: wat iemand kan, hoe lang het waarschijnlijk duurt en welke aanpassingen kunnen helpen.")
mc("hrm6-h12", W, H, "Hoe helpt e-HRM bij de Wet verbetering poortwachter?",
   ["Door de diagnose automatisch door te sturen naar de leidinggevende", "Door procesbewaking, zoals automatische meldingen voor UWV-deadlines, en gestructureerde dossieropbouw", "Door ziekmeldingen automatisch te weigeren", "Door de bedrijfsarts te vervangen"], 1,
   "E-HRM helpt met procesbewaking (deadlines), documentatie (standaardformats voor plan van aanpak en evaluaties), dossieropbouw (re-integratieverslag) en samenwerking tussen werkgever, werknemer, bedrijfsarts en HR.")

# ---------- Gespreksvoering MC ----------
mc("hrm6-g01", W, G, "Wat is géén doel van een verzuimgesprek volgens workshop 6?",
   ["Contact en bereikbaarheid afspreken", "Functionele mogelijkheden en aanpassingen bespreken", "Achterhalen wat de diagnose is", "Concrete vervolgafspraken maken"], 2,
   "Een verzuimgesprek gaat over werk, contact en inzetbaarheid. Het doel is niet een diagnose achterhalen, controleren of iemand echt ziek is, behandeling bespreken of schuld vaststellen.")
mc("hrm6-g02", W, G, "Welke vraag mag je als leidinggevende in een verzuimgesprek stellen?",
   ["'Wat is je diagnose?'", "'Welke medicijnen gebruik je?'", "'Wat is volgens de bedrijfsarts de verwachte duur?'", "'Waardoor ben je ziek geworden?'"], 2,
   "Vragen over werk, contact, het advies van de bedrijfsarts en functionele mogelijkheden mag je stellen. Diagnose, medicatie en oorzaak van de ziekte horen bij de bedrijfsarts en leg je niet vast.")
mc("hrm6-g03", W, G, "Wat is het doel van een gesprek over frequent kortdurend verzuim?",
   ["Het patroon bespreken en kijken naar preventie", "De re-integratie volgens het plan van aanpak bespreken", "Een officiële waarschuwing geven", "De diagnose achterhalen om het patroon te begrijpen"], 0,
   "Het doel verschilt per situatie: bij frequent kortdurend verzuim gaat het om patroon en preventie, bij langdurig verzuim om re-integratie en voortgang, bij werkhervatting om belastbaarheid, opbouw en evaluatie.")
mc("hrm6-g04", W, G, "Een medewerker is ziek na een conflict met een collega. Wat is het doel van het verzuimgesprek?",
   ["Het conflict in dit gesprek volledig uitpraten", "De werkcontext bespreken en een passende, aparte vervolginterventie bepalen, bijvoorbeeld bemiddeling", "Vaststellen wie schuld heeft", "Het gesprek uitstellen tot de medewerker beter is"], 1,
   "Bij spanning of conflict houd je contact, voorkom je dat het verzuimgesprek een volledig conflictgesprek wordt, en spreek je een aparte vervolgactie af.")
mc("hrm6-g05", W, G, "Hoe open je een gesprek over frequent verzuim volgens het principe 'van oordeel naar waarneming'?",
   ["'Je bent de laatste tijd wel erg vaak ziek.'", "'In de afgelopen zes maanden heb je je drie keer kortdurend ziek gemeld. Ik wil dit patroon met je bespreken en kijken wat nodig is rond werk en ondersteuning.'", "'Collega's beginnen zich zorgen te maken over jouw verzuim.'", "'Ik vraag me af of je wel echt ziek was.'"], 1,
   "Je benoemt feiten en het doel, zonder oordeel of verwijt. 'Erg vaak ziek' is een oordeel, en twijfel uitspreken over de ziekte hoort niet in een verzuimgesprek.")
mc("hrm6-g06", W, G, "Een medewerker begint uit zichzelf uitgebreid over zijn medische behandeling te vertellen. Wat zeg je?",
   ["Je noteert alles zorgvuldig voor het dossier", "'Dank dat je dat deelt. Ik leg medische details niet vast. Voor de medische beoordeling is de bedrijfsarts de juiste gesprekspartner. Laten we kijken wat dit betekent voor het werk.'", "Je vraagt door naar de details om het beter te begrijpen", "Je onderbreekt hem en zegt dat dit niet mag"], 1,
   "Je bewaakt de medische grens op een respectvolle manier: bedanken, uitleggen dat je het niet vastlegt, verwijzen naar de bedrijfsarts en terug naar werk en afspraken.")
mc("hrm6-g07", W, G, "Welke informatie verzamel je niet bij de voorbereiding van een verzuimgesprek?",
   ["De data van ziekmeldingen en contactmomenten", "Eerdere werkafspraken", "Informatie van collega's over mogelijke diagnoses", "Actuele informatie van de bedrijfsarts of arbodienst"], 2,
   "Niet verzamelen: medische vermoedens, informatie van collega's over diagnoses, persoonlijke gezondheidsgegevens en eigen conclusies over arbeidsongeschiktheid. Kernvraag: welke informatie heb ik nodig om over werk en afspraken te spreken?")
mc("hrm6-g08", W, G, "Wat is de tweede fase van het verzuimgesprek, na openen en contact maken?",
   ["Afspraken maken", "Doel en kader benoemen", "Belangen en ondersteuning verbinden", "Perspectief en mogelijkheden onderzoeken"], 1,
   "De zes fasen: openen en contact maken, doel en kader benoemen, feiten en werkcontext bespreken, perspectief en mogelijkheden onderzoeken, belangen en ondersteuning verbinden, afspraken maken en afsluiten.")
mc("hrm6-g09", W, G, "Wat is het doel van een gesprek bij werkhervatting?",
   ["Het patroon van verzuim bespreken", "Belastbaarheid, opbouw, taken en evaluatie afspreken", "Bepalen of de werknemer een waarschuwing krijgt", "De oorzaak van de ziekte achterhalen"], 1,
   "Bij werkhervatting gaat het om belastbaarheid, de opbouw van uren en taken, en een evaluatiemoment. Je baseert je op het advies van de bedrijfsarts.")
mc("hrm6-g10", W, G, "Welke vraag past het best bij 'onderzoekende vragen zonder de medische grens over te gaan'?",
   ["'Heb je al een specialist gezien?'", "'Waar loop je in het werk tegenaan?'", "'Is het psychisch of lichamelijk?'", "'Hoe gaat de behandeling?'"], 1,
   "Onderzoekende vragen gaan over het werk: hoe ervaar je het contact met het werk, welke werkzaamheden gaan goed, waar loop je tegenaan, welke ondersteuning verwacht je, wat kun je zelf bijdragen, wanneer evalueren we?")
mc("hrm6-g11", W, G, "Hoe geven observatoren in workshop 6 feedback?",
   ["Als cijfer van 1 tot 10", "Als top, tip en vraag", "Alleen schriftelijk aan de docent", "Als goed of fout"], 1,
   "Feedback in de vorm van top (wat ging goed), tip (wat kan beter) en vraag.")
mc("hrm6-g12", W, G, "Wat is volgens workshop 6 de rode draad van alle zes workshops, en dus wat de beoordelaar in het tentamengesprek wil zien?",
   ["Zo snel mogelijk een oplossing geven", "Feitelijk openen, luisteren, perspectief onderzoeken, structuur bewaken, belangen verbinden en afspraken maken", "Zo veel mogelijk theorie noemen tijdens het gesprek", "De acteur overtuigen van je eigen standpunt"], 1,
   "De rode draad: feitelijk openen, luisteren, perspectief onderzoeken, structuur bewaken, belangen verbinden, afspraken maken. Dat komt in elk gesprekstype terug.")

# ---------- Open vragen ----------
op("hrm6-ho1", W, H, "Leg het verschil uit tussen wit, grijs en zwart verzuim en tussen kortdurend, middellang en langdurend verzuim. Hoe ga je als facility manager om met grijs verzuim?",
   "Wit verzuim: aantoonbaar ziek, fysiek of psychisch. Grijs verzuim: onduidelijk ziektebeeld, iemand kan fysiek werken maar is moe of niet gemotiveerd. Zwart verzuim: geen ziekte, toch ziek gemeld. Duur: kortdurend maximaal een week, middellang een tot zes weken, langdurend langer dan zes weken. Bij grijs verzuim voer je een verzuimgesprek over werk en werkfactoren (werkdruk, rooster, sfeer, motivatie), zonder naar de diagnose te vragen, en verwijs je bij twijfel naar de bedrijfsarts. Je zoekt naar beïnvloedbare oorzaken en maakt afspraken over preventie.",
   ["Wit, grijs en zwart juist uitgelegd", "Drie duurcategorieën met de juiste grenzen", "Aanpak van grijs verzuim: gesprek over werkfactoren, geen diagnose, bedrijfsarts"])
op("hrm6-ho2", W, H, "Wat mag je als facility manager wel en niet bij verzuim onder de AVG? Wat is daarbij de rol van de bedrijfsarts?",
   "Gezondheidsgegevens zijn een bijzondere categorie persoonsgegevens. Niet: medische informatie vragen of registreren, oordelen over medische geschiktheid, medische dossiers of aantekeningen bijhouden, druk uitoefenen op herstel. Wel: functioneel informeren (werkgerelateerd), verzuim feitelijk administreren, re-integratie organiseren via de bedrijfsarts en contact houden zonder medische druk. De bedrijfsarts is een onafhankelijk medisch adviseur die zich richt op belastbaarheid en werkvermogen. Hij beoordeelt het werkvermogen, adviseert over re-integratie en geeft de werkgever alleen de noodzakelijke informatie: functionele mogelijkheden, vermoedelijke duur en mogelijke aanpassingen.",
   ["Minstens twee dingen die niet mogen", "Minstens twee dingen die wel mogen", "Rol bedrijfsarts: belastbaarheid, alleen noodzakelijke informatie"])
op("hrm6-ho3", W, H, "Je bent facility manager en wilt verzuim voorkomen. Noem per domein (fysiek, mentaal en sociaal welzijn) twee interventies, en geef aan waar je direct en waar je alleen indirect invloed hebt.",
   "Fysiek: ergonomische werkplekken en lichtere schoonmaakmachines, een goed binnenklimaat (ventilatie, temperatuur). Mentaal: roosters met voldoende hersteltijd, duidelijke taken en werkdrukbewaking. Sociaal: vaste teams en werkoverleg, aandacht voor sfeer en inclusie, een buddy voor nieuwe medewerkers. Direct invloed heb je op werkplek, ergonomie, binnenklimaat, roosters en materiaal. Op leefstijl en de privésituatie heb je alleen indirect invloed, bijvoorbeeld via een gezond aanbod in het bedrijfsrestaurant of voorlichting.",
   ["Twee interventies per domein", "Interventies zijn realistisch voor een FM'er", "Onderscheid directe en indirecte invloed"])
op("hrm6-go1", W, G, "Beschrijf de zes fasen van het verzuimgesprek en geef bij de eerste en laatste fase een voorbeeldzin.",
   "1. Openen en contact maken. Voorbeeld: 'Fijn dat je er bent. Hoe gaat het met je?' 2. Doel en kader benoemen: waarom je het gesprek voert en dat het over werk gaat, niet over de ziekte. 3. Feiten en werkcontext bespreken, neutraal. 4. Perspectief en mogelijkheden onderzoeken met open vragen. 5. Belangen en ondersteuning verbinden. 6. Afspraken maken en afsluiten. Voorbeeld: 'We spreken af dat je de komende twee weken drie ochtenden de balie doet, en we evalueren op 14 maart.'",
   ["Zes fasen in de juiste volgorde", "Voorbeeldzin bij openen", "Voorbeeldzin bij afsluiten met concrete afspraak en evaluatie"])
op("hrm6-go2", W, G, "Wat bespreek je wel en wat niet in een verzuimgesprek? Hoe reageer je als de medewerker toch medische informatie vertelt?",
   "Wel: werk en werkzaamheden, contact, het advies van de bedrijfsarts, functionele mogelijkheden, werkaanpassingen, impact op het team en re-integratieafspraken. Niet uitvragen: diagnose, behandeling, medicatie, medische geschiedenis en details van psychische of lichamelijke klachten. Als de medewerker het toch vertelt: 'Dank dat je dat deelt. Ik leg medische details niet vast. Voor de medische beoordeling is de bedrijfsarts de juiste gesprekspartner. Laten we kijken wat dit betekent voor het werk en onze afspraken.'",
   ["Minstens drie onderwerpen die je wel bespreekt", "Minstens drie onderwerpen die je niet uitvraagt", "Respectvolle reactie met verwijzing naar de bedrijfsarts"])
op("hrm6-go3", W, G, "Het doel van een verzuimgesprek verschilt per situatie. Noem vier situaties en het bijbehorende doel.",
   "Frequent kortdurend verzuim: patroon en preventie. Hoge werkbelasting: beïnvloedbare werkfactoren. Fysiek belastend werk: functionele mogelijkheden en aanpassingen. Langdurig verzuim: re-integratie en voortgang (plan van aanpak). Werkhervatting: belastbaarheid, opbouw, taken en evaluatie. Spanning of conflict: werkcontext en een passende, aparte vervolginterventie.",
   ["Vier situaties", "Bij elke situatie het juiste doel"])

# ---------- Casussen ----------
cs("hrm6-hc1", W, H, "Verzuim onder de loep",
   "Je bent net facility manager bij een facilitair bedrijf met 150 medewerkers in schoonmaak, receptie en catering. Het verzuim is in een jaar gestegen van 4% naar 9%. In die periode is er een nieuw groot contract bij gekomen, zijn er vacatures niet ingevuld en zijn de roosters vaker op het laatste moment gewijzigd. Eén schoonmaker is al 40 weken ziek. De directie vraagt jou om 'het verzuim omlaag te krijgen'.",
   [("Welke mogelijke oorzaken zie je? Cluster ze in categorieën.",
     "Werkgerelateerd: hogere werkdruk door het nieuwe contract en de open vacatures, onrustige roosters, mogelijk fysieke belasting. Organisatorische veranderingen: het nieuwe contract en de krapte. Persoonlijke oorzaken zijn ook mogelijk, maar daar heb je minder zicht en invloed op. Om dit te onderzoeken kijk je naar kengetallen, zoals meldingsfrequentie en gemiddelde verzuimduur per afdeling.",
     ["Oorzaken uit de casus herkend", "Logische clustering (werk, organisatie, persoonlijk)", "Kengetallen of onderzoeksvraag genoemd"]),
    ("Welke maatregelen neem je? Gebruik het idee van de FM'er als gezondheidsregisseur.",
     "Je bent niet verantwoordelijk voor de gezondheid zelf, maar wel voor de omstandigheden. Maatregelen: roosters eerder vastleggen en minder last-minute wijzigingen, de vacatures invullen of tijdelijk extra inzet regelen, werkdruk bespreken in werkoverleg, ergonomie en materiaal verbeteren, en leidinggevenden trainen in verzuimgesprekken bij frequent verzuim.",
     ["Kernidee: verantwoordelijk voor omstandigheden", "Minstens drie maatregelen die passen bij de oorzaken"]),
    ("Wat moet er gebeuren voor de schoonmaker die al 40 weken ziek is?",
     "Volgens de Wet verbetering poortwachter moet er al een probleemanalyse (week 6) en een plan van aanpak (week 8) zijn, met evaluaties elke 6 tot 8 weken. In week 42 moet de ziekmelding bij het UWV, dus dat moet nu direct geregeld worden. Daarna volgt de eerstejaarsevaluatie rond week 52. Kan hij niet terug in eigen of ander werk bij de werkgever, dan komt spoor 2 in beeld.",
     ["Ziekmelding UWV in week 42 (nu)", "Controle op probleemanalyse, plan van aanpak en evaluaties", "Eerstejaarsevaluatie of spoor 2 genoemd"])])
cs("hrm6-gc1", W, G, "Vijf ziekmeldingen van Sanne",
   "Je bent teamleider van de servicedesk (acht medewerkers) van een hogeschool. Sanne heeft zich in zes maanden vijf keer kort ziek gemeld. Ze werkt goed en klanten zijn tevreden over haar. Collega's nemen haar diensten over en de werkdruk in het team loopt op. Een collega vertelde je dat Sanne 'volgens haar migraine heeft'. Je plant een verzuimgesprek.",
   [("Wat neem je mee in je voorbereiding, en wat juist niet?",
     "Wel: de data van de ziekmeldingen en contactmomenten, eerdere werkafspraken, eventueel actuele informatie van de bedrijfsarts, de gevolgen voor het werk en het team, en relevante protocolregels. Niet: het vermoeden van migraine van de collega, eigen medische vermoedens of conclusies over arbeidsongeschiktheid. Het doel bij frequent kortdurend verzuim is patroon en preventie.",
     ["Minstens drie dingen die je wel verzamelt", "De informatie van de collega niet gebruiken", "Doel: patroon en preventie"]),
    ("Hoe open je het gesprek? Formuleer je eerste zinnen.",
     "Bijvoorbeeld: 'Fijn dat je er bent. Ik wil het met je hebben over je verzuim. In de afgelopen zes maanden heb je je vijf keer kort ziek gemeld. Ik wil dat patroon met je bespreken en samen kijken wat er nodig is rond werk, inzetbaarheid en ondersteuning. Het gaat dus niet over wat je precies hebt.'",
     ["Feitelijk, zonder oordeel", "Doel en kader benoemd (werk, niet de ziekte)"]),
    ("Sanne zegt: 'Ik heb gewoon vaak hoofdpijn, de dokter weet ook niet goed wat het is.' Hoe ga je verder en hoe sluit je af?",
     "Bewaak de medische grens: 'Dank dat je dat deelt. Ik leg medische details niet vast; voor de medische kant is de bedrijfsarts de juiste persoon.' Vraag dan naar werkfactoren: 'Zijn er dingen in het werk die het lastiger maken, bijvoorbeeld de schermtijd, het licht of de drukte?' Verbind de belangen (haar gezondheid en de werkdruk in het team) en maak een concrete afspraak, bijvoorbeeld een verwijzing naar het spreekuur van de bedrijfsarts en een aanpassing van haar werkplek, met een evaluatie over zes weken.",
     ["Medische grens respectvol bewaakt", "Vragen naar werkfactoren", "Concrete afspraak met evaluatiemoment"])])
cs("hrm6-gc2", W, G, "De terugkeer van Linda",
   "Linda is facilitair coördinator (gebouwbeheer, leveranciers, werkplekondersteuning). Ze is bijna vier maanden afwezig geweest. De bedrijfsarts adviseert een geleidelijke hervatting: de eerste twee weken drie ochtenden per week, zonder leverancierscontacten, daarna opbouwen. Haar collega's hebben haar taken overgenomen en vragen wanneer 'alles weer normaal' is. Je voert het gesprek over haar terugkeer.",
   [("Wat is het doel van dit gesprek en waar baseer je de afspraken op?",
     "Het doel bij werkhervatting is belastbaarheid, opbouw, taken en evaluatie: de re-integratie praktisch organiseren. Je baseert de afspraken op het advies van de bedrijfsarts, niet op je eigen inschatting ('volgens mij kun je best meer') en niet op de druk van collega's.",
     ["Doel werkhervatting juist", "Afspraken gebaseerd op advies bedrijfsarts"]),
    ("Welke concrete afspraken maak je met Linda?",
     "Uren: de eerste twee weken drie ochtenden. Taken: bijvoorbeeld gebouwbeheer en werkplekondersteuning, maar nog geen leverancierscontacten; die blijven bij een collega. Prioriteiten: wat moet eerst, wat kan blijven liggen. Ondersteuning: een vast aanspreekpunt en contactmomenten. Evaluatie: na twee weken kijken jullie samen hoe het gaat en hoe de opbouw verder gaat.",
     ["Uren en taken volgens het advies", "Ondersteuning of aanspreekpunt", "Evaluatiemoment"]),
    ("Hoe ga je om met de vraag van de collega's?",
     "Je benoemt de teamimpact zorgvuldig zonder medische informatie te delen. Je vertelt dat Linda geleidelijk terugkomt en welke taken zij voorlopig wel en niet doet, en je regelt dat de overgebleven taken eerlijk verdeeld blijven. Je deelt niets over de reden van haar verzuim.",
     ["Geen medische informatie delen", "Duidelijkheid over taken en verdeling"])])
